function results = opf_case74ds(gen_PMAX_12, gen_PMIN_4, gen_GENCOST_C1_3)
    define_constants;
    mpc = loadcase('case74ds');

    %% Generator at bus 12: reduce maximum available power (cooling limitation)
    gen12_idx = find(mpc.gen(:, GEN_BUS) == 12);
    assert(~isempty(gen12_idx), 'Generator at bus 12 not found');
    pmax0_12 = mpc.gen(gen12_idx(1), PMAX);
    mpc.gen(gen12_idx(1), PMAX) = gen_PMAX_12;
    assert(gen_PMAX_12 <= pmax0_12, 'Parameter must decrease according to scenario');

    %% Generator at bus 4: increase minimum stable output (high minimum generation)
    gen4_idx = find(mpc.gen(:, GEN_BUS) == 4);
    assert(~isempty(gen4_idx), 'Generator at bus 4 not found');
    pmin0_4 = mpc.gen(gen4_idx(1), PMIN);
    mpc.gen(gen4_idx(1), PMIN) = gen_PMIN_4;
    assert(gen_PMIN_4 >= pmin0_4, 'Parameter must increase according to scenario');

    %% Generator at bus 3: reduce linear cost coefficient to prioritize nuclear access
    gen3_idx = find(mpc.gen(:, GEN_BUS) == 3);
    assert(~isempty(gen3_idx), 'Generator at bus 3 not found');
    ncost3 = mpc.gencost(gen3_idx(1), NCOST);
    % Cost coefficients occupy columns COST : COST+NCOST-1, ordered from highest order to constant term
    % c1 column index = COST + (NCOST - 2)
    c1_col = COST + (ncost3 - 2);
    c1_0_3 = mpc.gencost(gen3_idx(1), c1_col);
    mpc.gencost(gen3_idx(1), c1_col) = gen_GENCOST_C1_3;
    assert(gen_GENCOST_C1_3 <= c1_0_3, 'Parameter must decrease according to scenario');

    mpopt = mpoption('opf.violation', 1e-8, 'opf.ac.solver', 'MIPS');
    results = runopf(mpc, mpopt);
    printpf(results);
end

function results = opf_case69(bus_PD_4, bus_QD_28, bus_VMIN_65, branch_RATE_A_4_26, branch_BR_R_54_29)
    define_constants;
    mpc = loadcase('case69');

    %% Bus 4: increase active demand (heat wave surge)
    bus4_idx = find(mpc.bus(:, BUS_I) == 4);
    pd0_bus4 = mpc.bus(bus4_idx, PD);
    mpc.bus(bus4_idx, PD) = bus_PD_4;
    assert(bus_PD_4 >= pd0_bus4, 'Parameter must increase according to scenario');

    %% Bus 28: increase reactive demand (industrial support needs)
    bus28_idx = find(mpc.bus(:, BUS_I) == 28);
    qd0_bus28 = mpc.bus(bus28_idx, QD);
    mpc.bus(bus28_idx, QD) = bus_QD_28;
    assert(bus_QD_28 >= qd0_bus28, 'Parameter must increase according to scenario');

    %% Bus 65: relax lower voltage threshold under stress
    bus65_idx = find(mpc.bus(:, BUS_I) == 65);
    vmin0_bus65 = mpc.bus(bus65_idx, VMIN);
    mpc.bus(bus65_idx, VMIN) = bus_VMIN_65;
    assert(bus_VMIN_65 <= vmin0_bus65, 'Parameter must decrease according to scenario');

    %% Branch 4-26: derate thermal capacity
    br426_idx = find((mpc.branch(:, F_BUS) == 4 & mpc.branch(:, T_BUS) == 26) | (mpc.branch(:, F_BUS) == 26 & mpc.branch(:, T_BUS) == 4));
    rateA0_426 = mpc.branch(br426_idx(1), RATE_A);
    mpc.branch(br426_idx(1), RATE_A) = branch_RATE_A_4_26;
    assert(branch_RATE_A_4_26 <= rateA0_426, 'Parameter must decrease according to scenario');

    %% Branch 54-29: increase resistance due to aging conductors
    br5429_idx = find((mpc.branch(:, F_BUS) == 54 & mpc.branch(:, T_BUS) == 29) | (mpc.branch(:, F_BUS) == 29 & mpc.branch(:, T_BUS) == 54));
    brr0_5429 = mpc.branch(br5429_idx(1), BR_R);
    mpc.branch(br5429_idx(1), BR_R) = branch_BR_R_54_29;
    assert(branch_BR_R_54_29 >= brr0_5429, 'Parameter must increase according to scenario');

    mpopt = mpoption('opf.violation', 1e-7, 'opf.ac.solver', 'MIPS');
    results = runopf(mpc, mpopt);
    printpf(results);
end

function results = opf_case118(gen_PMIN_14, gen_GENCOST_C1_9, gen_GENCOST_C2_7)
    define_constants;
    mpc = loadcase('case118');

    %% Generator at bus 14: increase minimum generation (forced water-determined output)
    gen14_idx = find(mpc.gen(:, GEN_BUS) == 14);
    assert(~isempty(gen14_idx), 'Generator at bus 14 not found');
    original_pmin_14 = mpc.gen(gen14_idx(1), PMIN);
    mpc.gen(gen14_idx(1), PMIN) = gen_PMIN_14;
    assert(gen_PMIN_14 >= original_pmin_14, 'Parameter must increase according to scenario');

    %% Generator at bus 9: decrease linear cost coefficient (lower bidding to ensure dispatch)
    gen9_idx = find(mpc.gen(:, GEN_BUS) == 9);
    assert(~isempty(gen9_idx), 'Generator at bus 9 not found');
    % Determine c1 column robustly: c0 is last column, c1 is second-to-last
    c1_col = size(mpc.gencost, 2) - 1;
    original_c1_9 = mpc.gencost(gen9_idx(1), c1_col);
    mpc.gencost(gen9_idx(1), c1_col) = gen_GENCOST_C1_9;
    assert(gen_GENCOST_C1_9 <= original_c1_9, 'Parameter must decrease according to scenario');

    %% Generator at bus 7: decrease quadratic cost coefficient (more aggressive price reduction)
    gen7_idx = find(mpc.gen(:, GEN_BUS) == 7);
    assert(~isempty(gen7_idx), 'Generator at bus 7 not found');
    % Determine c2 column robustly: c2 is third-to-last when polynomial cost is used
    c2_col = size(mpc.gencost, 2) - 2;
    original_c2_7 = mpc.gencost(gen7_idx(1), c2_col);
    mpc.gencost(gen7_idx(1), c2_col) = gen_GENCOST_C2_7;
    assert(gen_GENCOST_C2_7 <= original_c2_7, 'Parameter must decrease according to scenario');

    %% Solver options
    mpopt = mpoption('opf.violation', 1e-7, 'opf.ac.solver', 'MIPS');

    %% Run OPF
    results = runopf(mpc, mpopt);
    printpf(results);
end

