function results = opf_case70da(gen_PMIN_12, gen_GENCOST_C1_3, gen_GENCOST_C2_7)
    define_constants;
    mpc = loadcase('case70da');

    %% Generator at bus 12: enforce higher minimum output (forced water-determined generation)
    gen12_idx = find(mpc.gen(:, GEN_BUS) == 12);
    assert(~isempty(gen12_idx), 'Generator at bus 12 not found');
    gen12_idx = gen12_idx(1);
    original_pmin_12 = mpc.gen(gen12_idx, PMIN);
    mpc.gen(gen12_idx, PMIN) = gen_PMIN_12;
    assert(gen_PMIN_12 >= original_pmin_12, 'Parameter must increase according to scenario');

    %% Generator at bus 3: lower bid via linear cost term
    gen3_idx = find(mpc.gen(:, GEN_BUS) == 3);
    assert(~isempty(gen3_idx), 'Generator at bus 3 not found');
    gen3_idx = gen3_idx(1);
    N3 = mpc.gencost(gen3_idx, NCOST);
    assert(N3 >= 2, 'Generator cost at bus 3 must have at least a linear term');
    c1_col_3 = COST + (N3 - 2);  % position of c1 for polynomial cost
    original_c1_3 = mpc.gencost(gen3_idx, c1_col_3);
    mpc.gencost(gen3_idx, c1_col_3) = gen_GENCOST_C1_3;
    assert(gen_GENCOST_C1_3 <= original_c1_3, 'Parameter must decrease according to scenario');

    %% Generator at bus 7: lower bid via quadratic cost term
    gen7_idx = find(mpc.gen(:, GEN_BUS) == 7);
    assert(~isempty(gen7_idx), 'Generator at bus 7 not found');
    gen7_idx = gen7_idx(1);
    N7 = mpc.gencost(gen7_idx, NCOST);
    assert(N7 >= 3, 'Generator cost at bus 7 must have at least a quadratic term');
    c2_col_7 = COST + (N7 - 3);  % position of c2 for polynomial cost
    original_c2_7 = mpc.gencost(gen7_idx, c2_col_7);
    mpc.gencost(gen7_idx, c2_col_7) = gen_GENCOST_C2_7;
    assert(gen_GENCOST_C2_7 <= original_c2_7, 'Parameter must decrease according to scenario');

    %% Solver options
    mpopt = mpoption('opf.ac.solver', 'MIPS');

    %% Run OPF
    results = runopf(mpc, mpopt);
    printpf(results);
end

