    ratea0_818 = mpc.branch(br818_idx(1), RATE_A);
    mpc.branch(br818_idx(1), RATE_A) = branch_RATE_A_8_18;
    assert(branch_RATE_A_8_18 <= ratea0_818, 'Parameter must decrease according to scenario');

