    bus14_idx = find(mpc.bus(:, BUS_I) == 14);
    vmin0_bus14 = mpc.bus(bus14_idx, VMIN);
    mpc.bus(bus14_idx, VMIN) = bus_VMIN_14;
    assert(bus_VMIN_14 <= vmin0_bus14, 'Parameter must decrease according to scenario');

    %% Branch 13-12: increase resistance due to hotter conductors
    br1312_idx = find((mpc.branch(:, F_BUS) == 13 & mpc.branch(:, T_BUS) == 12) | (mpc.branch(:, F_BUS) == 12 & mpc.branch(:, T_BUS) == 13));
