    c1_col_41 = COST + (n41 - 2);  % position of linear coefficient
    original_c1_41 = mpc.gencost(gen41, c1_col_41);
    mpc.gencost(gen41, c1_col_41) = gen_GENCOST_C1_41;
    assert(gen_GENCOST_C1_41 >= original_c1_41, 'Parameter must increase according to scenario');

    %% Generator at bus 6: increase available capacity (flexible unit expansion)
