    assert(~isempty(gen2_idx), 'Generator at bus 2 not found');
    gen2_row = gen2_idx(1);
    orig_pmax_gen2 = mpc.gen(gen2_row, PMAX);
    mpc.gen(gen2_row, PMAX) = gen_PMAX_2;
    assert(gen_PMAX_2 >= orig_pmax_gen2, 'Parameter must increase according to scenario');

    %% OPF options and run
    mpopt = mpoption('opf.ac.solver', 'MIPS');
    results = runopf(mpc, mpopt);
    printpf(results);
end

function results = opf_case39(bus_PD_14, bus_QD_31, bus_VMAX_11, bus_BS_19, gen_PMAX_6)
define_constants;
mpc = loadcase('case39');

%% Bus 14: reflect industrial load reduction (decrease active demand)
bus14_idx = find(mpc.bus(:, BUS_I) == 14);
original_bus_PD_14 = mpc.bus(bus14_idx, PD);
mpc.bus(bus14_idx, PD) = bus_PD_14;
assert(bus_PD_14 <= original_bus_PD_14, 'Parameter must decrease according to scenario');

%% Bus 31: reactive demand reduction (decrease reactive demand)
bus31_idx = find(mpc.bus(:, BUS_I) == 31);
original_bus_QD_31 = mpc.bus(bus31_idx, QD);
mpc.bus(bus31_idx, QD) = bus_QD_31;
assert(bus_QD_31 <= original_bus_QD_31, 'Parameter must decrease according to scenario');

%% Bus 11: allow higher voltage headroom (increase voltage upper limit)
bus11_idx = find(mpc.bus(:, BUS_I) == 11);
original_bus_VMAX_11 = mpc.bus(bus11_idx, VMAX);
mpc.bus(bus11_idx, VMAX) = bus_VMAX_11;
assert(bus_VMAX_11 >= original_bus_VMAX_11, 'Parameter must increase according to scenario');

%% Bus 19: disconnect capacitor/shunt (set shunt susceptance to zero)
bus19_idx = find(mpc.bus(:, BUS_I) == 19);
mpc.bus(bus19_idx, BS) = bus_BS_19;
assert(bus_BS_19 == 0, 'Parameter must be set to zero according to scenario');

%% Generator at bus 6: provide additional headroom for renewable-rich conditions (increase max active power)
gen6_idx = find(mpc.gen(:, GEN_BUS) == 6);
original_gen_PMAX_6 = mpc.gen(gen6_idx, PMAX);
mpc.gen(gen6_idx, PMAX) = gen_PMAX_6;
assert(gen_PMAX_6 >= original_gen_PMAX_6, 'Parameter must increase according to scenario');

%% Solver options
mpopt = mpoption('opf.violation', 1e-7, 'opf.ac.solver', 'MIPS');

%% Run OPF
results = runopf(mpc, mpopt);
printpf(results);
end

