function results = opf_case33bw(bus_PD_16, bus_QD_23, gen_PMAX_3, gen_GENCOST_C1_1)
    define_constants;
    mpc = loadcase('case33bw');

    %% Bus 16: decrease active demand during nighttime valley
    bus16_idx = find(mpc.bus(:, BUS_I) == 16);
    pd0_bus16 = mpc.bus(bus16_idx, PD);
    mpc.bus(bus16_idx, PD) = bus_PD_16;
    assert(bus_PD_16 <= pd0_bus16, 'Parameter must decrease according to scenario');

    %% Bus 23: decrease reactive demand
    bus23_idx = find(mpc.bus(:, BUS_I) == 23);
    qd0_bus23 = mpc.bus(bus23_idx, QD);
    mpc.bus(bus23_idx, QD) = bus_QD_23;
    assert(bus_QD_23 <= qd0_bus23, 'Parameter must decrease according to scenario');

    %% Generator at bus 3: increase available renewable capacity
    gen3_idx = find(mpc.gen(:, GEN_BUS) == 3);
    pmax0_gen3 = mpc.gen(gen3_idx(1), PMAX);
    mpc.gen(gen3_idx(1), PMAX) = gen_PMAX_3;
    assert(gen_PMAX_3 >= pmax0_gen3, 'Parameter must increase according to scenario');

    %% Generator at bus 1: lower marginal cost (C1 coefficient)
    gen1_idx = find(mpc.gen(:, GEN_BUS) == 1);
    gc1_idx = gen1_idx(1);
    model1 = mpc.gencost(gc1_idx, MODEL);
    nc1 = mpc.gencost(gc1_idx, NCOST);
    assert(model1 == POLYNOMIAL, 'Expected polynomial cost model for generator at bus 1 to modify C1');
    assert(nc1 >= 2, 'Cost function must include a linear term (C1)');
    c1_col = COST + (nc1 - 2);  % position of C1 in polynomial cost coefficients
    c1_0 = mpc.gencost(gc1_idx, c1_col);
    mpc.gencost(gc1_idx, c1_col) = gen_GENCOST_C1_1;
    assert(gen_GENCOST_C1_1 <= c1_0, 'Parameter must decrease according to scenario');

    %% OPF options: tight feasibility tolerance, MIPS solver
    mpopt = mpoption('opf.violation', 1e-8, 'opf.ac.solver', 'MIPS');

    results = runopf(mpc, mpopt);
    printpf(results);
end

function results = opf_case94pi(gen_PMAX_12, bus_PD_59, bus_BS_40, bus_VMAX_30, bus_VMIN_93, gen_QMAX_11)
    define_constants;
