    pd0_b59 = mpc.bus(bus59_idx, PD);
    mpc.bus(bus59_idx, PD) = bus_PD_59;
    assert(bus_PD_59 >= pd0_b59, 'Parameter must increase according to scenario');

    %% Bus 40: reactive compensation device failed (remove shunt support)
